                        su = a % 16;
                        if ((ty == 1) || (((su == 1) && (zone == 1)) || ((su == 2) && (zone == 2)))) {
                            sup += 1;
                        } else {
                            oth += 1;
                        }
                    } else {
                        t = m;
                        while (t >= 0) {
                            if (Evidence.MkGet(mk, t, Evidence.MkfMcid()) >= 0) {
                                con += 1;
                                t = -1;
                            } else {
                                t = Evidence.MkGet(mk, t, Evidence.MkfParent());
                            }
                        }
                    }
                }
            }
            k += 1;
        }
        if (tot == 0) {
            return 0;
        }
        if ((sup * 10) >= (tot * 6)) {
            return 1;
        }
        if ((oth * 10) >= (tot * 6)) {
            return 3;
        }
        if ((con * 10) >= (tot * 6)) {
            return 2;
        }
        return 0;
    }
    internal static int FuZoneFloor(int h) {
        // D583 (smoke review B issue 11): twice the depth (centipoints) of the margin zones of a page `h` tall when 11 per cent of it is less than FU_FLOOR (36 pt) and 17 per cent of it more
        // than 11 per cent: a page the size of a slide or a small card (210 pt tall) has a running header 18 pt from its top edge and a footer 28 pt from its foot, outside 11 per cent
        // of it. 0 for a page where 11 per cent is deep enough (every page of a letter's size and over 327 pt tall).
        int lim = FuMin(2 * FuFloor, (h * FuFcap) / 500);
        if (lim > ((h * FuTop) / 500)) {
            return lim;
        }
        return 0;
    }
    internal static int FuRowCells(emon.Port.Cells ln, int l) {
        // D583 (smoke review A issue 15): how many upright lines (this one included) of its page stand on line l's baseline (centres within half its height), among the 40 lines either side of it
        // in the text layer's order. A row of FU_CELLS or more in the top zone is a table's row, not a running header (a left, a centre and a right part at the most; a footer of four parts or more is a footer: the real statement's): the first data row of a
        // continuation page, directly under the repeated header, recurs by position and by the shape of its cells and passed as a header that varies.
        int nl = Evidence.LnCount(ln);
        int c2 = Evidence.LnGet(ln, l, Evidence.LhY0()) + Evidence.LnGet(ln, l, Evidence.LhY1());
        int half = FuMax(1, Evidence.LnGet(ln, l, Evidence.LhY1()) - Evidence.LnGet(ln, l, Evidence.LhY0()));
        int p = Evidence.LnGet(ln, l, Evidence.LhPage());
        int q = FuMax(0, l - 40);
        int n = 0;
        int rot = 0;
        while ((q < nl) && (q <= (l + 40))) {
            rot = Evidence.LnGet(ln, q, Evidence.LhRot());
            if ((Evidence.LnGet(ln, q, Evidence.LhPage()) == p) && (((rot < 100) || (rot > 35900)) && (FuAbs((Evidence.LnGet(ln, q, Evidence.LhY0()) + Evidence.LnGet(ln, q, Evidence.LhY1())) - c2) <= half))) {
                n += 1;
            }
            q += 1;
        }
        return n;
    }
    internal static int FuScan(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells gl, emon.Port.Cells mk, emon.Port.Cells pages, int npages, emon.Port.Cells cd, emon.Port.Cells sl, emon.Port.Cells tx) {
        // Every candidate line of the document as a row of `cd`, in line order. Answers the number of rows, or -1 when the
        // lines are not in page order (nothing here is then safe to say).
        int nl = Evidence.LnCount(ln);
        int l = 0;
        int p = 0;
        int prev = 0;
        int w = 0;
        int h = 0;
        int rot = 0;
        int zone = 0;
        int cy2 = 0;
        int cx2 = 0;
        int ts = 0;
        int tl = 0;
        int r = 0;
        while (l < nl) {
            p = Evidence.LnGet(ln, l, Evidence.LhPage());
            if (p < prev) {
                return -1;
            }
            if (p > prev) {
                prev = p;
            }
            if ((p >= 1) && (p <= npages)) {
                w = Model.PageW(pages, p - 1);
                h = Model.PageH(pages, p - 1);
                rot = Evidence.LnGet(ln, l, Evidence.LhRot());
                zone = 0;
                cy2 = Evidence.LnGet(ln, l, Evidence.LhY0()) + Evidence.LnGet(ln, l, Evidence.LhY1());
                cx2 = Evidence.LnGet(ln, l, Evidence.LhX0()) + Evidence.LnGet(ln, l, Evidence.LhX1());
                if ((rot < 100) || (rot > 35900)) {
                    int fz = FuZoneFloor(h);
                    if (cy2 < FuMax(fz, (h * FuTop) / 500)) {
                        zone = 1;
                    }
                    if (fz > 0) {
                        if (cy2 > ((2 * h) - fz)) {
                            zone = 2;
                        }
                    } else if (cy2 > ((h * FuBot) / 500)) {
                        zone = 2;
                    }
                } else if ((FuAbs(rot - 9000) < 100) || (FuAbs(rot - 27000) < 100)) {
                    if ((cx2 < ((w * FuSide) / 500)) || (cx2 > ((w * (1000 - FuSide)) / 500))) {
                        zone = 3;
                    }
                }
                if ((zone == 1) && (FuRowCells(ln, l) >= FuCells)) {
                    zone = 0;
                }
                if (zone > 0) {
                    ts = emon.Port.CellsLen(tx);
                    tl = FuLineText(wd, ln, et, tx, l);
                    if ((tl == 0) || (tl > FuMaxlen)) {
                        emon.Port.CellsDrop(tx, ts);
                    } else {
                        r = FuPushRow(cd, 16);
                        CdSet(cd, r, 0, l);
                        CdSet(cd, r, 1, p);
                        CdSet(cd, r, 2, zone);
                        CdSet(cd, r, 3, Evidence.LnGet(ln, l, Evidence.LhY0()));
                        CdSet(cd, r, 4, Evidence.LnGet(ln, l, Evidence.LhY1()));
                        CdSet(cd, r, 8, -1);
                        CdSet(cd, r, 11, ts);
                        CdSet(cd, r, 12, tl);
                        FuSlots(tx, ts, tl, sl, cd, r);
                        CdSet(cd, r, 9, FuTag(wd, ln, gl, mk, l, zone));
                        int w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
                        CdSet(cd, r, 14, Evidence.WdGet(wd, w0, Evidence.WfSize()));
                    }
                }
            }
            l += 1;
        }
        return emon.Port.CellsLen(cd) / 16;
    }
    internal static int FuKey(emon.Port.Cells cd, int mode, int r, int k) {
        if (mode == 0) {
            if (k == 0) {
                return CdGet(cd, r, 2);
            }
            if (k == 1) {
                return CdGet(cd, r, 6);
            }
            if (k == 2) {
                return CdGet(cd, r, 5);
            }
            if (k == 3) {
                return CdGet(cd, r, 3);
            }
            return CdGet(cd, r, 1);
        }
        if (mode == 1) {
            if (k == 0) {
                return CdGet(cd, r, 8);
            }
            if (k == 1) {
                return CdGet(cd, r, 1);
            }
            return 0;
        }
        if (k == 0) {
            return CdGet(cd, r, 2);
        }
        if (k == 1) {
            return (CdGet(cd, r, 14) + 25) / 50;
        }
        if (k == 2) {
            return CdGet(cd, r, 3);
        }
        if (k == 3) {
            return CdGet(cd, r, 1);
        }
        return 0;
    }
    internal static int FuBefore(emon.Port.Cells cd, int mode, int a, int b) {
        // 1 when row a sorts before row b: lexicographic on the mode's five keys, then the row (a total order).
        int k = 0;
        int x = 0;
        int y = 0;
        while (k < 5) {
            x = FuKey(cd, mode, a, k);
            y = FuKey(cd, mode, b, k);
            if (x < y) {
                return 1;
            }
            if (x > y) {
                return 0;
            }
            k += 1;
        }
        if (a < b) {
            return 1;
        }
        return 0;
    }
    internal static int FuSort(emon.Port.Cells ord, emon.Port.Cells cd, int mode) {
        // Shell sort of the row indices in `ord` (Knuth's gaps).
        int n = emon.Port.CellsLen(ord);
        int h = 1;
        int i = 0;
        int j = 0;
        int v = 0;
        int u = 0;
        int more = 1;
        while (h < (n / 3)) {
            h = (h * 3) + 1;
        }
        while (h >= 1) {
            i = h;
            while (i < n) {
                v = emon.Port.CellsAt(ord, i);
                j = i;
                more = 1;
                while ((j >= h) && (more == 1)) {
                    u = emon.Port.CellsAt(ord, j - h);
                    if (FuBefore(cd, mode, v, u) == 1) {
                        emon.Port.CellsSet(ord, j, u);
                        j -= h;
                    } else {
                        more = 0;
                    }
                }
                emon.Port.CellsSet(ord, j, v);
                i += 1;
            }
            h = (h - 1) / 3;
        }
        return 0;
    }
    internal static int FuCluster(emon.Port.Cells ord, emon.Port.Cells cd, emon.Port.Cells gr, emon.Port.Cells pages, int mode) {
        // Sort `ord` by the mode's keys and cut it into groups: a new group where the zone, the hash (mode 0) or the size
        // (mode 2) change, or the vertical position moves more than FU_YTOL per mille of the page's height from the member
        // before it. Fills `gr`'s kind, zone, first position and members, and every row's group. Answers the number of groups.
        FuSort(ord, cd, mode);
        emon.Port.CellsDrop(gr, 0);
        int n = emon.Port.CellsLen(ord);
        int i = 0;
        int g = -1;
        int r = 0;
        int q = 0;
        int cut = 0;
        int tol = 0;
        while (i < n) {
            r = emon.Port.CellsAt(ord, i);
            cut = 1;
            if (i > 0) {
                q = emon.Port.CellsAt(ord, i - 1);
                tol = (Model.PageH(pages, CdGet(cd, r, 1) - 1) * FuYtol) / 1000;
                if (CdGet(cd, r, 2) == CdGet(cd, q, 2)) {
                    if (mode == 0) {
                        if ((CdGet(cd, r, 5) == CdGet(cd, q, 5)) && (CdGet(cd, r, 6) == CdGet(cd, q, 6))) {
                            if ((CdGet(cd, r, 3) - CdGet(cd, q, 3)) <= tol) {
                                cut = 0;
                            }
                        }
                    } else if (FuKey(cd, 2, r, 1) == FuKey(cd, 2, q, 1)) {
                        if ((CdGet(cd, r, 3) - CdGet(cd, q, 3)) <= tol) {
                            cut = 0;
                        }
                    }
                }
            }
            if (cut == 1) {
                g = FuPushRow(gr, 16);
                GrSet(gr, g, 0, i);
                GrSet(gr, g, 3, CdGet(cd, r, 2));
                if (mode == 0) {
                    GrSet(gr, g, 5, 1);
                } else {
                    GrSet(gr, g, 5, 2);
                }
                GrSet(gr, g, 6, -1);
                GrSet(gr, g, 7, -1);
            }
            GrInc(gr, g, 1);
            CdSet(cd, r, 8, g);
            i += 1;
        }
        return emon.Port.CellsLen(gr) / 16;
    }
    internal static int FuStats(emon.Port.Cells ord, emon.Port.Cells cd, emon.Port.Cells gr) {
        // Per group: the distinct pages and the tag evidence for and against, over its members (in page order).
        int ng = emon.Port.CellsLen(gr) / 16;
        int g = 0;
        int i = 0;
        int r = 0;
        int prev = 0;
        int f = 0;
        int m = 0;
        while (g < ng) {
            f = GrGet(gr, g, 0);
            m = GrGet(gr, g, 1);
            prev = -1;
            GrSet(gr, g, 2, 0);
            GrSet(gr, g, 10, 0);
            GrSet(gr, g, 11, 0);
            i = 0;
            while (i < m) {
                r = emon.Port.CellsAt(ord, f + i);
                if (CdGet(cd, r, 1) != prev) {
                    GrInc(gr, g, 2);
                    prev = CdGet(cd, r, 1);
                }
                if (CdGet(cd, r, 9) == 1) {
                    GrInc(gr, g, 10);
                }
                if (CdGet(cd, r, 9) == 2) {
                    GrInc(gr, g, 11);
                }
                i += 1;
            }
            g += 1;
        }
        return 0;
    }
    internal static int FuIsoCount(emon.Port.Cells ord, emon.Port.Cells cd, emon.Port.Cells gr) {
        // Per group: how many members are isolated (gr 9).
        int ng = emon.Port.CellsLen(gr) / 16;
        int g = 0;
        int i = 0;
        int f = 0;
        int m = 0;
        int r = 0;
        while (g < ng) {
            f = GrGet(gr, g, 0);
            m = GrGet(gr, g, 1);
            GrSet(gr, g, 9, 0);
            i = 0;
            while (i < m) {
                r = emon.Port.CellsAt(ord, f + i);
                if (CdGet(cd, r, 10) >= FuIsogap) {
                    GrInc(gr, g, 9);
                }
                i += 1;
            }
            g += 1;
        }
        return 0;
    }
    internal static int FuIso(emon.Port.Cells ln, emon.Port.Cells cd, emon.Port.Cells gr, int ncd) {
        // Isolation (3): for each candidate, is the nearest other line toward the inside of the page at least half a line
        // away? The lines that are members of a template group seen on two or more pages do not count: they are the
        // furniture. A margin line is isolated by definition. Answers 0.
        int nl = Evidence.LnCount(ln);
        int l = 0;
        int e = 0;
        int p = 0;
        int r0 = 0;
        int r1 = 0;
        int r = 0;
        int q = 0;
        int l2 = 0;
        int best = 0;
        int y0 = 0;
        int y1 = 0;
        int gap = 0;
        int cy2 = 0;
        int rot = 0;
        int skip = 0;
        int rr = 0;
        while (l < nl) {
            p = Evidence.LnGet(ln, l, Evidence.LhPage());
            e = l;
            while ((e < nl) && (Evidence.LnGet(ln, e, Evidence.LhPage()) == p)) {
                e += 1;
            }
            while ((r0 < ncd) && (CdGet(cd, r0, 1) < p)) {
                r0 += 1;
            }
            r1 = r0;
            while ((r1 < ncd) && (CdGet(cd, r1, 1) == p)) {
                r1 += 1;
            }
            r = r0;
            while (r < r1) {
                if (CdGet(cd, r, 2) == 3) {
                    CdSet(cd, r, 10, 100000);
                } else {
                    y0 = CdGet(cd, r, 3);
                    y1 = CdGet(cd, r, 4);
                    best = 1000000000;
                    q = r0;
                    l2 = l;
                    while (l2 < e) {
                        skip = 0;
                        if (l2 == CdGet(cd, r, 0)) {
                            skip = 1;
                        }
                        rot = Evidence.LnGet(ln, l2, Evidence.LhRot());
                        if ((rot >= 100) && (rot <= 35900)) {
                            skip = 1;
                        }
                        while ((q < r1) && (CdGet(cd, q, 0) < l2)) {
                            q += 1;
                        }
                        if ((q < r1) && (CdGet(cd, q, 0) == l2)) {
                            rr = CdGet(cd, q, 8);
                            if (GrGet(gr, rr, 2) >= 2) {
                                skip = 1;
                            }
                        }
                        if (skip == 0) {
                            cy2 = Evidence.LnGet(ln, l2, Evidence.LhY0()) + Evidence.LnGet(ln, l2, Evidence.LhY1());
                            if (CdGet(cd, r, 2) == 1) {
                                if (cy2 > (2 * y1)) {
                                    gap = Evidence.LnGet(ln, l2, Evidence.LhY0()) - y1;
                                    if (gap < best) {
                                        best = gap;
                                    }
                                }
                            }
                            if (CdGet(cd, r, 2) == 2) {
                                if (cy2 < (2 * y0)) {
                                    gap = y0 - Evidence.LnGet(ln, l2, Evidence.LhY1());
                                    if (gap < best) {
                                        best = gap;
                                    }
                                }
                            }
                        }
                        l2 += 1;
                    }
                    best = FuMin(best, 1000000);
                    if (best < -1000000) {
                        best = -1000000;
                    }
                    CdSet(cd, r, 10, (best * 1000) / FuMax(1, y1 - y0));
                }
                r += 1;
            }
            r0 = r1;
            l = e;
        }
        return 0;
    }
    internal static int FuSlotValue(emon.Port.Cells cd, emon.Port.Cells sl, int r, int j) {
        return SlGet(sl, CdGet(cd, r, 13) + j, 2);
    }
    internal static int FuSlotKind(emon.Port.Cells cd, emon.Port.Cells sl, int r, int j) {
        return SlGet(sl, CdGet(cd, r, 13) + j, 1);
    }
    internal static int FuClassBit(int j) {
        // 4 to the j: where the two bits of slot j's class sit in gr 14.
        int v = 1;
        int i = 0;
        while (i < j) {
            v *= 4;
            i += 1;
        }
        return v;
    }
    internal static int FuAnalyze(emon.Port.Cells ord, emon.Port.Cells cd, emon.Port.Cells sl, emon.Port.Cells gr, int g) {
        // Classify each slot of the group's template over its members, in page order: 1 the same on every page, 2 follows
        // the page (the value steps by the page step in at least FU_PAIRS per cent of consecutive pairs), 3 varies. The first
        // standalone slot that follows the page is the PAGE SLOT; the first embedded one is the EMBEDDED slot, `exact` (gr 15)
        // when every pair stepped and its value is the page index. A group varies (gr 12) when a slot varies or an embedded
        // slot is not exact. Answers 0.
        int f = GrGet(gr, g, 0);
        int m = GrGet(gr, g, 1);
        int rep = emon.Port.CellsAt(ord, f);
        int ns = CdGet(cd, rep, 7);
        int j = 0;
        int i = 0;
        int cls = 0;
        int bits = 0;
        int same = 0;
        int npairs = 0;
        int nok = 0;
        int r = 0;
        int pr = 0;
        int v = 0;
        int pv = 0;
        int kind = 0;
        GrSet(gr, g, 6, -1);
        GrSet(gr, g, 7, -1);
        GrSet(gr, g, 12, 0);
        GrSet(gr, g, 13, ns);
        GrSet(gr, g, 14, 0);
        GrSet(gr, g, 15, 0);
        if (ns < 1) {
            return 0;
        }
        while (j < ns) {
            same = 1;
            npairs = 0;
            nok = 0;
            pr = rep;
            pv = FuSlotValue(cd, sl, rep, j);
            i = 1;
            while (i < m) {
                r = emon.Port.CellsAt(ord, f + i);
                v = FuSlotValue(cd, sl, r, j);
                if (v != FuSlotValue(cd, sl, rep, j)) {
                    same = 0;
                }
                if (CdGet(cd, r, 1) != CdGet(cd, pr, 1)) {
                    npairs += 1;
                    if ((v >= 0) && ((pv >= 0) && ((v - pv) == (CdGet(cd, r, 1) - CdGet(cd, pr, 1))))) {
                        nok += 1;
                    }
                }
                pr = r;
                pv = v;
                i += 1;
            }
            cls = 3;
            if (same == 1) {
                cls = 1;
            }
            if ((cls == 3) && ((npairs >= 1) && ((nok * 100) >= (npairs * FuPairs)))) {
                cls = 2;
            }
            kind = FuSlotKind(cd, sl, rep, j);
            bits += cls * FuClassBit(j);
            if (cls == 3) {
                GrSet(gr, g, 12, 1);
            }
            if (cls == 2) {
                if ((kind != 3) && (GrGet(gr, g, 6) == -1)) {
                    GrSet(gr, g, 6, j);
                } else if ((kind == 3) && (GrGet(gr, g, 7) == -1)) {
                    GrSet(gr, g, 7, j);
                    if ((nok == npairs) && (FuSlotValue(cd, sl, rep, j) == CdGet(cd, rep, 1))) {
                        GrSet(gr, g, 15, 1);
                    }
                } else {
                    GrSet(gr, g, 12, 1);
                }
            }
            j += 1;
        }
        GrSet(gr, g, 14, bits);
        if ((GrGet(gr, g, 7) >= 0) && (GrGet(gr, g, 15) == 0)) {
            GrSet(gr, g, 12, 1);
        }
        return 0;
    }
    internal static int FuQualify(emon.Port.Cells ord, emon.Port.Cells cd, emon.Port.Cells sl, emon.Port.Cells tx, emon.Port.Cells gr, int g, int npages, int trust) {
        // SPEC 10.2 step 1 and D076: does the template group qualify as furniture? The score is the recurrence (300 for one
        // page, 500 + 150 per page beyond, at most 1000) plus FU_TAGW tenths of `trust` times the share of members that are
        // tagged artifacts in place minus the share that are tagged content; it needs FU_QUAL, and the coverage (at least
        // FU_COVER per cent of the pages, or 3 pages for a page number, or the tree's word) and the isolation (at least
        // FU_ISOPCT per cent of the members, or a page number, or the tree's word). A page number the tree marks Pagination is
        // taken from one page. Answers 1 or 0 and sets gr 4, 8.
        int f = GrGet(gr, g, 0);
        int m = GrGet(gr, g, 1);
        int c = GrGet(gr, g, 2);
        int rep = emon.Port.CellsAt(ord, f);
        int ns = CdGet(cd, rep, 7);
        int s = (GrGet(gr, g, 10) * 1000) / m;
        int o = (GrGet(gr, g, 11) * 1000) / m;
        int er = 300;
        int score = 0;
        int pagelike = 0;
        int covok = 0;
        int isook = 0;
        int tag = 0;
        GrSet(gr, g, 4, 0);
        GrSet(gr, g, 8, 0);
        if (ns < 0) {
            return 0;
        }
        if ((GrGet(gr, g, 12) == 1) && (FuCaptionLead(tx, cd, rep) == 1)) {
            return 0;
        }
        if (c >= 2) {
            er = FuMin(1000, 500 + (150 * c));
        }
        score = er + ((((trust * (s - o)) / 1000) * FuTagw) / 10);
        GrSet(gr, g, 8, FuMax(0, FuMin(1000, score)));
        if ((s >= 800) && (trust >= 300)) {
            tag = 1;
        }
        if (GrGet(gr, g, 6) >= 0) {
            pagelike = 1;
        }
        if ((c * 100) >= (npages * FuCover)) {
            covok = 1;
        }
        if ((pagelike == 1) && (c >= 3)) {
            covok = 1;
        }
        if (tag == 1) {
            covok = 1;
        }
        if ((GrGet(gr, g, 9) * 100) >= (m * FuIsopct)) {
            isook = 1;
        }
        if (pagelike == 1) {
            isook = 1;
        }
        if (tag == 1) {
            isook = 1;
        }
        if (GrGet(gr, g, 3) == 3) {
            covok = 0;
            if ((c >= 3) && ((c * 100) >= (npages * 50))) {
                covok = 1;
            }
        }
        if ((score >= FuQual) && ((covok == 1) && (isook == 1))) {
            GrSet(gr, g, 4, 1);
            return 1;
        }
        return 0;
    }
    internal static int FuChainAdjacent(emon.Port.Cells ln, emon.Port.Cells cd, int ncd, int r) {
        // 1 when candidate r has, on its page and in its zone, a candidate that qualified (cell 15 is 1) directly toward the page's edge from it: within FU_CHAIN_GAP per mille
        // of its own height of it, and its left edge within two heights of r's (the first line of a two-line header, over the second). Not a cell of a table's row (FU_CELLS
        // candidates on its baseline).
        int lo = FuMax(0, r - 30);
        int hi = FuMin(ncd, r + 31);
        int h = FuMax(1, CdGet(cd, r, 4) - CdGet(cd, r, 3));
        int c2 = CdGet(cd, r, 3) + CdGet(cd, r, 4);
        int q = lo;
        int n = 0;
        int gap = 0;
        while (q < hi) {
            if ((CdGet(cd, q, 1) == CdGet(cd, r, 1)) && ((CdGet(cd, q, 2) == CdGet(cd, r, 2)) && (FuAbs((CdGet(cd, q, 3) + CdGet(cd, q, 4)) - c2) <= h))) {
                n += 1;
            }
            q += 1;
        }
        if (n >= FuCells) {
            return 0;
        }
        q = lo;
        while (q < hi) {
            if ((q != r) && ((CdGet(cd, q, 1) == CdGet(cd, r, 1)) && ((CdGet(cd, q, 2) == CdGet(cd, r, 2)) && ((CdGet(cd, q, 15) == 1) && (FuAbs(Evidence.LnGet(ln, CdGet(cd, q, 0), Evidence.LhX0()) - Evidence.LnGet(ln, CdGet(cd, r, 0), Evidence.LhX0())) <= (2 * h)))))) {
                if (CdGet(cd, r, 2) == 1) {
                    gap = CdGet(cd, r, 3) - CdGet(cd, q, 4);
                    if ((gap >= -200) && ((gap * 1000) <= (h * FuChainGap)) && (CdGet(cd, q, 3) < CdGet(cd, r, 3))) {
                        return 1;
                    }
                }
                if (CdGet(cd, r, 2) == 2) {
                    gap = CdGet(cd, q, 3) - CdGet(cd, r, 4);
                    if ((gap >= -200) && ((gap * 1000) <= (h * FuChainGap)) && (CdGet(cd, q, 3) > CdGet(cd, r, 3))) {
                        return 1;
                    }
                }
            }
            q += 1;
        }
        return 0;
    }
    internal static int FuChain(emon.Port.Cells ln, emon.Port.Cells ord, emon.Port.Cells cd, emon.Port.Cells sl, emon.Port.Cells tx, emon.Port.Cells gr, int ng, int ncd, int npages, int trust) {
        // D583 (smoke review B issue 11): a template group that qualified in everything but its isolation, whose every member (at least 70 per cent) lies directly under or over a member of a group that
        // qualified, on the same page and in the same zone, is the next line of that header or footer: a two-line running header has its second line against the body, and only
        // the first is set apart (the lines that recur do not count). Qualified groups are marked (cell 15 is 1) so a third line goes with the second. Answers the groups added.
        int pass = 0;
        int changed = 1;
        int added = 0;
        int g = 0;
        int i = 0;
        int adj = 0;
        int old = 0;
        int f = 0;
        int m = 0;
        while ((changed == 1) && (pass < 3)) {
            changed = 0;
            g = 0;
            while (g < ng) {
                if ((GrGet(gr, g, 4) == 0) && ((GrGet(gr, g, 2) >= 2) && ((GrGet(gr, g, 3) == 1) || (GrGet(gr, g, 3) == 2)))) {
                    f = GrGet(gr, g, 0);
                    m = GrGet(gr, g, 1);
                    adj = 0;
                    i = 0;
                    while (i < m) {
                        adj += FuChainAdjacent(ln, cd, ncd, emon.Port.CellsAt(ord, f + i));
                        i += 1;
                    }
                    if ((adj * 100) >= (m * 70)) {
                        old = GrGet(gr, g, 9);
                        GrSet(gr, g, 9, m);
                        if (FuQualify(ord, cd, sl, tx, gr, g, npages, trust) == 1) {
                            i = 0;
                            while (i < m) {
                                CdSet(cd, emon.Port.CellsAt(ord, f + i), 15, 1);
                                i += 1;
                            }
                            added += 1;
                            changed = 1;
                        } else {
                            GrSet(gr, g, 9, old);
                        }
                    }
                }
                g += 1;
            }
            pass += 1;
        }
        return added;
    }
    internal static int FuNormCp(int c) {
        // What a character is in a comparison of titles: a letter or a digit, lowercase; 0 for anything else.
        if (FuAlnum(c) == 0) {
            return 0;
        }
        return FuLower(c);
    }
    internal static long FuHashCells(emon.Port.Cells c, int s, int n) {
        int i = 0;
        int x = 0;
        long h = FuBasis();
        while (i < n) {
            x = FuNormCp(emon.Port.CellsAt(c, s + i));
            if (x > 0) {
                h = FuStep(h, x);
            }
            i += 1;
        }
        return h;
    }
    internal static int FuNormLen(emon.Port.Cells c, int s, int n) {
        int i = 0;
        int k = 0;
        while (i < n) {
            if (FuNormCp(emon.Port.CellsAt(c, s + i)) > 0) {
                k += 1;
            }
            i += 1;
        }
        return k;
    }
    internal static long FuHashLines(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, int l0, int k) {
        // The hash of the normalised text of k consecutive lines read as one.
        int l = l0;
        int w = 0;
        int j = 0;
        int ts = 0;
        int tl = 0;
        int x = 0;
        long h = FuBasis();
        while (l < (l0 + k)) {
            w = 0;
            while (w < Evidence.LnGet(ln, l, Evidence.LhCount())) {
                ts = Evidence.WdGet(wd, Evidence.LnGet(ln, l, Evidence.LhFirst()) + w, Evidence.HdTstart());
                tl = Evidence.WdGet(wd, Evidence.LnGet(ln, l, Evidence.LhFirst()) + w, Evidence.HdTlen());
                if ((ts >= 0) && (tl > 0)) {
                    j = 0;
                    while (j < tl) {
                        x = FuNormCp(emon.Port.CellsAt(et, ts + j));
                        if (x > 0) {
                            h = FuStep(h, x);
                        }
                        j += 1;
                    }
                }
                w += 1;
            }
            l += 1;
        }
        return h;
    }
    internal static int FuLenLines(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, int l0, int k) {
        int l = l0;
        int w = 0;
        int n = 0;
        int ts = 0;
        int tl = 0;
        while (l < (l0 + k)) {
            w = 0;
            while (w < Evidence.LnGet(ln, l, Evidence.LhCount())) {
                ts = Evidence.WdGet(wd, Evidence.LnGet(ln, l, Evidence.LhFirst()) + w, Evidence.HdTstart());
                tl = Evidence.WdGet(wd, Evidence.LnGet(ln, l, Evidence.LhFirst()) + w, Evidence.HdTlen());
                if ((ts >= 0) && (tl > 0)) {
                    n += FuNormLen(et, ts, tl);
                }
                w += 1;
            }
            l += 1;
        }
        return n;
    }
    internal static int FuBhSort(emon.Port.Cells bh) {
        // Shell sort of the rows (low, high) of `bh` by (high, low).
        int n = emon.Port.CellsLen(bh) / 2;
        int h = 1;
        int i = 0;
        int j = 0;
        int lo = 0;
        int hi = 0;
        int more = 1;
        while (h < (n / 3)) {
            h = (h * 3) + 1;
        }
        while (h >= 1) {
            i = h;
            while (i < n) {
                lo = emon.Port.CellsAt(bh, i * 2);
                hi = emon.Port.CellsAt(bh, (i * 2) + 1);
                j = i;
                more = 1;
                while ((j >= h) && (more == 1)) {
                    if ((hi < emon.Port.CellsAt(bh, ((j - h) * 2) + 1)) || ((hi == emon.Port.CellsAt(bh, ((j - h) * 2) + 1)) && (lo < emon.Port.CellsAt(bh, (j - h) * 2)))) {
                        emon.Port.CellsSet(bh, j * 2, emon.Port.CellsAt(bh, (j - h) * 2));
                        emon.Port.CellsSet(bh, (j * 2) + 1, emon.Port.CellsAt(bh, ((j - h) * 2) + 1));
                        j -= h;
                    } else {
                        more = 0;
                    }
                }
                emon.Port.CellsSet(bh, j * 2, lo);
                emon.Port.CellsSet(bh, (j * 2) + 1, hi);
                i += 1;
            }
            h = (h - 1) / 3;
        }
        return 0;
    }
    internal static int FuBhHas(emon.Port.Cells bh, long h) {
        // Is the 64-bit hash one of the rows of the sorted `bh`?
        int lo = (int) h;
        int hi = (int) ((long)((ulong)(h) >> 32));
        int a = 0;
        int b = emon.Port.CellsLen(bh) / 2;
        int mid = 0;
        while (a < b) {
            mid = (a + b) / 2;
            if ((emon.Port.CellsAt(bh, mid * 2) == lo) && (emon.Port.CellsAt(bh, (mid * 2) + 1) == hi)) {
                return 1;
            }
            if ((emon.Port.CellsAt(bh, (mid * 2) + 1) < hi) || ((emon.Port.CellsAt(bh, (mid * 2) + 1) == hi) && (emon.Port.CellsAt(bh, mid * 2) < lo))) {
                a = mid + 1;
            } else {
                b = mid;
            }
        }
        return 0;
    }
    internal static int FuCdFind(emon.Port.Cells cd, int ncd, int l) {
        // The candidate row of line l (candidate rows are in line order), or -1.
        int a = 0;
        int b = ncd;
        int mid = 0;
        while (a < b) {
            mid = (a + b) / 2;
            if (CdGet(cd, mid, 0) == l) {
                return mid;
            }
            if (CdGet(cd, mid, 0) < l) {
                a = mid + 1;
            } else {
                b = mid;
            }
        }
        return -1;
    }
    internal static int FuBodyHashes(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells cd, int ncd, emon.Port.Cells txt, emon.Port.Cells md, emon.Port.Cells bh) {
        // The hashes of everything the output will say: every line that is not a member of a qualified group, alone and with
        // the one or two lines after it on the page, and the document's Info /Title, each of at least FU_MINNORM letters and
        // digits; sorted. A running title that is already one of them is the output saying it twice.
        emon.Port.CellsDrop(bh, 0);
        int nl = Evidence.LnCount(ln);
        int l = 0;
        int k = 0;
        int ok = 0;
        int q = 0;
        int p = 0;
        long h = 0;
        while (l < nl) {
            p = Evidence.LnGet(ln, l, Evidence.LhPage());
            k = 1;
            ok = 1;
            while ((k <= 3) && (ok == 1)) {
                if ((l + (k - 1)) >= nl) {
                    ok = 0;
                } else {
                    if (Evidence.LnGet(ln, l + (k - 1), Evidence.LhPage()) != p) {
                        ok = 0;
                    }
                    q = FuCdFind(cd, ncd, l + (k - 1));
                    if (q >= 0) {
                        if (CdGet(cd, q, 15) > 0) {
                            ok = 0;
                        }
                    }
                }
                if (ok == 1) {
                    if (FuLenLines(wd, ln, et, l, k) >= FuMinnorm) {
                        h = FuHashLines(wd, ln, et, l, k);
                        emon.Port.CellsPush(bh, (int) h);
                        emon.Port.CellsPush(bh, (int) ((long)((ulong)(h) >> 32)));
                    }
                }
                k += 1;
            }
            l += 1;
        }
        if ((emon.Port.CellsLen(md) > (FuMdTitle + 1)) && (emon.Port.CellsAt(md, FuMdTitle + 1) > 0)) {
            if (FuNormLen(txt, emon.Port.CellsAt(md, FuMdTitle), emon.Port.CellsAt(md, FuMdTitle + 1)) >= FuMinnorm) {
                h = FuHashCells(txt, emon.Port.CellsAt(md, FuMdTitle), emon.Port.CellsAt(md, FuMdTitle + 1));
                emon.Port.CellsPush(bh, (int) h);
                emon.Port.CellsPush(bh, (int) ((long)((ulong)(h) >> 32)));
            }
        }
        FuBhSort(bh);
        return 0;
    }
    internal static int FuTitleMatch(emon.Port.Cells bh, emon.Port.Cells c, int s, int n) {
        // Is the text c[s, s+n) (normalised) something the output already says? At least FU_MINNORM letters and digits.
        if (FuNormLen(c, s, n) < FuMinnorm) {
            return 0;
        }
        return FuBhHas(bh, FuHashCells(c, s, n));
    }
    internal static int FuNextTok(emon.Port.Cells tx, int i, int end, int tok) {
        // From i (just after the token numbered `tok`), the next token that is not only punctuation, as its ordinal * 8 + its
        // class (`fu-tclass`); -1 when there is none.
        int p = i;
        int e = 0;
        int cs = 0;
        int ce = 0;
        int k = 0;
        int n = tok + 1;
        while (p < end) {
            if (emon.Port.CellsAt(tx, p) == 32) {
                p += 1;
            } else {
                e = p;
                while ((e < end) && (emon.Port.CellsAt(tx, e) != 32)) {
                    e += 1;
                }
                cs = FuCs(tx, p, e);
                ce = FuCe(tx, cs, e);
                k = FuTclass(tx, cs, ce);
                if (k != 0) {
                    return (n * 8) + k;
                }
                n += 1;
                p = e;
            }
        }
        return -1;
    }
    internal static int FuDecomp(emon.Port.Cells tx, emon.Port.Cells cd, emon.Port.Cells sl, int r, int pj, int ej, int pad, emon.Port.Cells ft) {
        // What REMAINS of candidate r's text once the page numbering is taken out, appended to `ft`; answers its length.
        // With a PAGE SLOT `pj` (an ordinal among the candidate's slots; -1 none) out go: its token; a page word (`Page`, `Seite`)
        // next to it; an "of" word (`of`, `de`, `von`) before a number, and that number, the total; and the tokens that are only
        // punctuation. Without one the text is copied as it is. The EMBEDDED slot `ej`, when given, is written as the template `{n}`
        // (`{n:0W}` when `pad` is the width W of its zero-padded digits) in place of its digits.
        int bs = CdGet(cd, r, 11);
        int end = bs + CdGet(cd, r, 12);
        int first = CdGet(cd, r, 13);
        int start = emon.Port.CellsLen(ft);
        int pjtok = -1;
        int ejs = -1;
        int ejl = 0;
        int i = bs;
        int e = 0;
        int cs = 0;
        int ce = 0;
        int k = 0;
        int nx = 0;
        int prevslot = 0;
        int prevof = 0;
        int sepof = 0;
        int tok = 0;
        int skip = 0;
        int started = 0;
        int j = 0;
        if (pj >= 0) {
            pjtok = SlGet(sl, first + pj, 5);
        }
        if (ej >= 0) {
            ejs = bs + SlGet(sl, first + ej, 3);
            ejl = SlGet(sl, first + ej, 4);
        }
        while (i < end) {
            if (emon.Port.CellsAt(tx, i) == 32) {
                i += 1;
            } else {
                e = i;
                while ((e < end) && (emon.Port.CellsAt(tx, e) != 32)) {
                    e += 1;
                }
                cs = FuCs(tx, i, e);
                ce = FuCe(tx, cs, e);
                k = FuTclass(tx, cs, ce);
                nx = -1;
                if (pj >= 0) {
                    nx = FuNextTok(tx, e, end, tok);
                }
                skip = 0;
                if ((k == 0) && (pj >= 0)) {
                    skip = 1;
                }
                if (tok == pjtok) {
                    skip = 1;
                }
                if ((pj >= 0) && (k == 1)) {
                    if ((prevslot == 1) || ((nx >= 0) && ((nx / 8) == pjtok))) {
                        skip = 1;
                    }
                }
                if ((pj >= 0) && (k == 2)) {
                    if ((nx >= 0) && ((nx % 8) == 3)) {
                        skip = 1;
                    }
                }
                if ((pj >= 0) && ((k == 3) && ((prevof == 1) || (sepof == 1)))) {
                    skip = 1;
                }
                if (skip == 0) {
                    if (started == 1) {
                        emon.Port.CellsPush(ft, 32);
                    }
                    started = 1;
                    j = i;
                    while (j < e) {
                        if ((ejs >= 0) && (j == ejs)) {
                            emon.Port.CellsPush(ft, 123);
                            emon.Port.CellsPush(ft, 110);
                            if (pad > 0) {
                                emon.Port.CellsPush(ft, 58);
                                emon.Port.CellsPush(ft, 48);
                                emon.Port.CellsPush(ft, 48 + pad);
                            }
                            emon.Port.CellsPush(ft, 125);
                            j += ejl;
                        } else {
                            emon.Port.CellsPush(ft, emon.Port.CellsAt(tx, j));
                            j += 1;
                        }
                    }
                }
                if (k != 0) {
                    prevslot = 0;
                    if (tok == pjtok) {
                        prevslot = 1;
                    }
                    prevof = 0;
                    if ((k == 2) && (skip == 1)) {
                        prevof = 1;
                    }
                }
                if (k == 0) {
                    if (((e - i) == 1) && (emon.Port.CellsAt(tx, i) == 47)) {
                        sepof = 1;
                    }
                } else {
                    sepof = 0;
                }
                tok += 1;
                i = e;
            }
        }
        return emon.Port.CellsLen(ft) - start;
    }
    internal static int FuPagenumSlot(emon.Port.Cells tx, emon.Port.Cells cd, emon.Port.Cells sl, int r, int lone) {
        // For a candidate that is in no template group: the slot of its page number when the line says `page` in so many words
        // (a page word, and nothing else but numbers, "of" words and punctuation: `Seite 12`, `Page iv of x`), or is a number alone
        // and equal to the page's index (`12` on page 12); else -1.
        int bs = CdGet(cd, r, 11);
        int end = bs + CdGet(cd, r, 12);
        int first = CdGet(cd, r, 13);
        int ns = CdGet(cd, r, 7);
        int i = bs;
        int e = 0;
        int cs = 0;
        int ce = 0;
        int k = 0;
        int words = 0;
        int ntok = 0;
        int j = 0;
        if (ns < 1) {
            return -1;
        }
        while (i < end) {
            if (emon.Port.CellsAt(tx, i) == 32) {
                i += 1;
            } else {
                e = i;
                while ((e < end) && (emon.Port.CellsAt(tx, e) != 32)) {
                    e += 1;
                }
                cs = FuCs(tx, i, e);
                ce = FuCe(tx, cs, e);
                k = FuTclass(tx, cs, ce);
                if ((k == 5) && (FuPrefixed(tx, cs, ce) < 0)) {
                    return -1;
                }
                if (k == 1) {
                    words += 1;
                }
                if (k != 0) {
                    ntok += 1;
                }
                i = e;
            }
        }
        if (words == 0) {
            if ((ntok == 1) && (lone == 1) && (SlGet(sl, first, 1) != 3)) {
                return 0;
            }
            if ((ntok == 1) && ((SlGet(sl, first, 1) == 1) && (SlGet(sl, first, 2) == CdGet(cd, r, 1)))) {
                return 0;
            }
            if ((ntok == 1) && (SlGet(sl, first, 1) == 4)) {
                return 0;
            }
            return -1;
        }
        while (j < ns) {
            if (SlGet(sl, first + j, 1) != 3) {
                return j;
            }
            j += 1;
        }
        return -1;
    }
    internal static int FuPad(emon.Port.Cells ord, emon.Port.Cells cd, emon.Port.Cells sl, emon.Port.Cells gr, int g, int ej) {
        // The width W of a zero-padded embedded number (`ACME-01`): every member has W digits and some value is shorter
        // than W digits; else 0 (the template is `{n}`).
        int f = GrGet(gr, g, 0);
        int m = GrGet(gr, g, 1);
        int w = SlGet(sl, CdGet(cd, emon.Port.CellsAt(ord, f), 13) + ej, 6);
        int i = 0;
        int r = 0;
        int lim = 1;
        int padded = 0;
        int s = 0;
        if ((w < 2) || (w > 9)) {
            return 0;
        }
        while ((i + 1) < w) {
            lim *= 10;
            i += 1;
        }
        i = 0;
        while (i < m) {
            r = emon.Port.CellsAt(ord, f + i);
            s = CdGet(cd, r, 13) + ej;
            if (SlGet(sl, s, 6) != w) {
                return 0;
            }
            if (SlGet(sl, s, 2) < lim) {
                padded = 1;
            }
            i += 1;
        }
        if (padded == 1) {
            return w;
        }
        return 0;
    }
    internal static int FuOutLedger(emon.Port.Cells fo, int reason, int page, int x0, int y0, int x1, int y1, int conf, int src, int ts, int tl) {
        int r = FuPushRow(fo, 12);
        emon.Port.CellsSet(fo, (r * 12) + 0, 1);
        emon.Port.CellsSet(fo, (r * 12) + 1, reason);
        emon.Port.CellsSet(fo, (r * 12) + 2, page);
        emon.Port.CellsSet(fo, (r * 12) + 3, x0);
        emon.Port.CellsSet(fo, (r * 12) + 4, y0);
        emon.Port.CellsSet(fo, (r * 12) + 5, x1);
        emon.Port.CellsSet(fo, (r * 12) + 6, y1);
        emon.Port.CellsSet(fo, (r * 12) + 7, conf);
        emon.Port.CellsSet(fo, (r * 12) + 8, src);
        emon.Port.CellsSet(fo, (r * 12) + 9, ts);
        emon.Port.CellsSet(fo, (r * 12) + 10, tl);
        return r;
    }
    internal static int FuOutFurniture(emon.Port.Cells fo, int role, int conf, int src, int ts, int tl, int f0, int cnt) {
        int r = FuPushRow(fo, 12);
        emon.Port.CellsSet(fo, (r * 12) + 0, 2);
        emon.Port.CellsSet(fo, (r * 12) + 1, role);
        emon.Port.CellsSet(fo, (r * 12) + 2, conf);
        emon.Port.CellsSet(fo, (r * 12) + 3, src);
        emon.Port.CellsSet(fo, (r * 12) + 4, ts);
        emon.Port.CellsSet(fo, (r * 12) + 5, tl);
        emon.Port.CellsSet(fo, (r * 12) + 6, f0);
        emon.Port.CellsSet(fo, (r * 12) + 7, cnt);
        return r;
    }
    internal static int FuFpPush(emon.Port.Cells fp, int page, int x0, int y0, int x1, int y1) {
        emon.Port.CellsPush(fp, page);
        emon.Port.CellsPush(fp, x0);
        emon.Port.CellsPush(fp, y0);
        emon.Port.CellsPush(fp, x1);
        emon.Port.CellsPush(fp, y1);
        return 0;
    }
    internal static int FuCopy(emon.Port.Cells src, int s, int n, emon.Port.Cells ft) {
        // Append src[s, s+n) to `ft`; answer where it starts.
        int at = emon.Port.CellsLen(ft);
        int i = 0;
        while (i < n) {
            emon.Port.CellsPush(ft, emon.Port.CellsAt(src, s + i));
            i += 1;
        }
        return at;
    }
    internal static int FuLabel(emon.Port.Cells pl, int page, int score, int ts, int tl) {
        // Offer a page's label; the best score keeps it, the first of equals.
        int at = (page - 1) * 3;
        if (score > emon.Port.CellsAt(pl, at)) {
            emon.Port.CellsSet(pl, at, score);
            emon.Port.CellsSet(pl, at + 1, ts);
            emon.Port.CellsSet(pl, at + 2, tl);
        }
        return 0;
    }
    internal static int FuRole(int zone) {
        if (zone == 1) {
            return Model.RlHeader();
        }
        if (zone == 2) {
            return Model.RlFooter();
        }
        return Model.RlMargin();
    }
    internal static int FuEmitGroup(emon.Port.Cells ln, emon.Port.Cells cd, emon.Port.Cells sl, emon.Port.Cells gr, emon.Port.Cells ord, emon.Port.Cells tx, emon.Port.Cells bh, emon.Port.Cells fo, emon.Port.Cells fp, emon.Port.Cells ft, emon.Port.Cells pl, int g, int mode) {
        // Decide a qualified group (SPEC 10.2 step 3) and write the outcomes: per member the page label and the ledger rows,
        // and the furniture rows. A template group whose members are the same beyond the page (not `varying`) is one furniture
        // row for all of them; a style group, or a group with a varying slot, is decomposed member by member. `mode` 2 drops what
        // policy would keep (a `running-title` row says so). Marks the members' lines for removal (cd 15). Answers 0.
        int f = GrGet(gr, g, 0);
        int m = GrGet(gr, g, 1);
