    internal static int FuSortNums(emon.Port.Cells c) {
        // Shell sort of the numbers in `c`, ascending.
        int n = emon.Port.CellsLen(c);
        int h = 1;
        int i = 0;
        int j = 0;
        int v = 0;
        int u = 0;
        int more = 1;
        while (h < (n / 3)) {
            h = (h * 3) + 1;
        }
        while (h >= 1) {
            i = h;
            while (i < n) {
                v = emon.Port.CellsAt(c, i);
                j = i;
                more = 1;
                while ((j >= h) && (more == 1)) {
                    u = emon.Port.CellsAt(c, j - h);
                    if (v < u) {
                        emon.Port.CellsSet(c, j, u);
                        j -= h;
                    } else {
                        more = 0;
                    }
                }
                emon.Port.CellsSet(c, j, v);
                i += 1;
            }
            h = (h - 1) / 3;
        }
        return 0;
    }
    internal static int FuBodySize(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells cd, int ncd, emon.Port.Cells bh) {
        // The most common size (to a fifth of a point) of the first word of the lines that are not candidates: the body text's.
        // 0 when there is none. `bh` is scratch.
        emon.Port.CellsDrop(bh, 0);
        int nl = Evidence.LnCount(ln);
        int l = 0;
        int q = 0;
        int best = 0;
        int bestn = 0;
        int run = 0;
        int i = 0;
        int v = 0;
        int w0 = 0;
        while (l < nl) {
            if (Evidence.LnGet(ln, l, Evidence.LhCount()) >= 1) {
                q = FuCdFind(cd, ncd, l);
                if (q < 0) {
                    w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
                    emon.Port.CellsPush(bh, Evidence.WdGet(wd, w0, Evidence.WfSize()) / 20);
                }
            }
            l += 1;
        }
        FuSortNums(bh);
        i = 0;
        while (i < emon.Port.CellsLen(bh)) {
            v = emon.Port.CellsAt(bh, i);
            if ((i > 0) && (v == emon.Port.CellsAt(bh, i - 1))) {
                run += 1;
            } else {
                run = 1;
            }
            if (run > bestn) {
                bestn = run;
                best = v;
            }
            i += 1;
        }
        emon.Port.CellsDrop(bh, 0);
        return best * 20;
    }
    internal static int FuStylePass(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells txt, emon.Port.Cells md, emon.Port.Cells cd, int ncd, emon.Port.Cells sl, emon.Port.Cells gr, emon.Port.Cells ord, emon.Port.Cells tx, emon.Port.Cells bh, emon.Port.Cells fo, emon.Port.Cells fp, emon.Port.Cells ft, emon.Port.Cells pl, emon.Port.Cells pages, int npages, int trust, int bsz, int mode) {
        // SPEC 10.2's recurrence for running text that VARIES (evidence 6): among the candidates in the tighter bands, groups
