        int g = 0;
        int i = 0;
        int f = 0;
        int m = 0;
        int c = 0;
        int iso = 0;
        int free = 0;
        int ok = 0;
        int con = 0;
        int capt = 0;
        int longest = 0;
        r = 0;
        while (r < ncd) {
            h = Model.PageH(pages, CdGet(cd, r, 1) - 1);
