    internal static int FuWatermarks(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, int npages, int bsz, emon.Port.Cells fo, emon.Port.Cells ft) {
        // Large text set on the diagonal (at least 3 degrees off every right angle) and at least two and a half times the body
        // size, a few words long: a watermark (`DRAFT`, `CONFIDENTIAL`). It is not content: it is taken out of the flow and the
        // ledger says `watermark`. (Visibility and the tree's /Watermark artifacts, P3.5-P3.7, are the sharper evidence; this is
        // the geometry.) Answers the number of lines taken.
        int nl = Evidence.LnCount(ln);
        int l = 0;
        int p = 0;
        int rot = 0;
        int dev = 0;
        int w0 = 0;
        int ts = 0;
        int tl = 0;
        int taken = 0;
        if (bsz <= 0) {
            return 0;
        }
        while (l < nl) {
            p = Evidence.LnGet(ln, l, Evidence.LhPage());
            if ((p >= 1) && (p <= npages)) {
                rot = Evidence.LnGet(ln, l, Evidence.LhRot()) % 9000;
                dev = rot;
                if ((9000 - rot) > 0) {
                    if ((9000 - rot) < dev) {
                        dev = 9000 - rot;
                    }
                }
                w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
                if ((dev >= 300) && ((Evidence.LnGet(ln, l, Evidence.LhCount()) >= 1) && (Evidence.LnGet(ln, l, Evidence.LhCount()) <= 4))) {
                    if ((Evidence.WdGet(wd, w0, Evidence.WfSize()) * 100) >= (bsz * 250)) {
                        ts = emon.Port.CellsLen(ft);
                        tl = FuLineText(wd, ln, et, ft, l);
                        if ((tl > 0) && (tl <= 40)) {
                            FuOutLedger(fo, Model.DrWatermark(), p, Evidence.LnGet(ln, l, Evidence.LhX0()), Evidence.LnGet(ln, l, Evidence.LhY0()), Evidence.LnGet(ln, l, Evidence.LhX1()), Evidence.LnGet(ln, l, Evidence.LhY1()), 600, Model.SrText() + Model.SrInfer(), ts, tl);
                            Evidence.LnSet(ln, l, Evidence.LhPage(), -7);
                            taken += 1;
                        } else {
                            emon.Port.CellsDrop(ft, ts);
                        }
                    }
                }
            }
            l += 1;
        }
        return taken;
    }
    internal static int FuStamps(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells pages, int npages, emon.Port.Cells cd, int ncd, emon.Port.Cells fo, emon.Port.Cells fp, emon.Port.Cells ft) {
