    internal static int FuFoKey(emon.Port.Cells fo, emon.Port.Cells fp, int r, int k) {
        if (k == 0) {
            return FoGet(fo, r, 9);
        }
        if (k == 1) {
            return FoGet(fo, r, 8);
        }
        if (k == 2) {
            return FoGet(fo, r, 1);
