    internal static int FuFoBefore(emon.Port.Cells fo, emon.Port.Cells fp, int a, int b) {
        int k = 0;
        int x = 0;
        int y = 0;
        while (k < 4) {
            x = FuFoKey(fo, fp, a, k);
            y = FuFoKey(fo, fp, b, k);
            if (x < y) {
                return 1;
            }
            if (x > y) {
                return 0;
            }
            k += 1;
        }
        if (a < b) {
            return 1;
        }
        return 0;
    }
    internal static int FuMergeFurniture(emon.Port.Cells fo, emon.Port.Cells fp, emon.Port.Cells ft, emon.Port.Cells ord) {
