                        emon.Port.CellsSet(ord, j, u);
                        j -= h;
                    } else {
                        more = 0;
                    }
                }
                emon.Port.CellsSet(ord, j, v);
                i += 1;
            }
            h = (h - 1) / 3;
        }
        i = 0;
