        emon.Port.CellsDrop(tx, 0);
        emon.Port.CellsDrop(bh, 0);
        emon.Port.CellsDrop(fo, 0);
        emon.Port.CellsDrop(fp, 0);
        emon.Port.CellsDrop(ft, 0);
        emon.Port.CellsDrop(pl, 0);
        int p = 0;
        int n = 0;
        int ng = 0;
        int g = 0;
        int r = 0;
        int before = Evidence.LnCount(ln);
        int bsz = 0;
        int ts = 0;
        int nn = 0;
        while (p < npages) {
            emon.Port.CellsPush(pl, 0);
            emon.Port.CellsPush(pl, -1);
            emon.Port.CellsPush(pl, 0);
            p += 1;
        }
        if ((emon.Port.CellsLen(md) > FuMdRanges) && (emon.Port.CellsAt(md, FuMdRanges) > 0)) {
            p = 0;
            while (p < npages) {
                ts = emon.Port.CellsLen(ft);
                nn = Pdfmeta.PmLabelCells(txt, lb, p, ft);
                if (nn > 0) {
                    FuLabel(pl, p + 1, 5000, ts, nn);
                }
                p += 1;
            }
        }
        if (mode == 1) {
            return 0;
        }
        n = FuScan(wd, ln, et, gl, mk, pages, npages, cd, sl, tx);
        if (n < 0) {
            return 0;
        }
        if (n >= 1) {
            r = 0;
            while (r < n) {
                emon.Port.CellsPush(ord, r);
                r += 1;
            }
            ng = FuCluster(ord, cd, gr, pages, 0);
            FuSort(ord, cd, 1);
            FuStats(ord, cd, gr);
            FuIso(ln, cd, gr, n);
            FuIsoCount(ord, cd, gr);
            g = 0;
            while (g < ng) {
                FuAnalyze(ord, cd, sl, gr, g);
                if ((GrGet(gr, g, 2) == 1) && ((trust >= 300) && ((GrGet(gr, g, 10) * 1000) >= (GrGet(gr, g, 1) * 800)))) {
                    r = emon.Port.CellsAt(ord, GrGet(gr, g, 0));
                    nn = FuPagenumSlot(tx, cd, sl, r, 1);
                    GrSet(gr, g, 6, nn);
                }
                FuQualify(ord, cd, sl, tx, gr, g, npages, trust);
                if (GrGet(gr, g, 4) == 1) {
                    r = 0;
                    while (r < GrGet(gr, g, 1)) {
                        CdSet(cd, emon.Port.CellsAt(ord, GrGet(gr, g, 0) + r), 15, 1);
                        r += 1;
                    }
                }
                g += 1;
            }
            FuChain(ln, ord, cd, sl, tx, gr, ng, n, npages, trust);
            FuBodyHashes(wd, ln, et, cd, n, txt, md, bh);
            r = 0;
            while (r < n) {
                if (CdGet(cd, r, 15) == 1) {
                    CdSet(cd, r, 15, 0);
                }
                r += 1;
            }
            g = 0;
            while (g < ng) {
                if (GrGet(gr, g, 4) == 1) {
                    FuEmitGroup(ln, cd, sl, gr, ord, tx, bh, fo, fp, ft, pl, g, mode);
                }
                g += 1;
            }
        }
        bsz = FuBodySize(wd, ln, cd, n, bh);
        if (n >= 1) {
            FuStylePass(wd, ln, et, txt, md, cd, n, sl, gr, ord, tx, bh, fo, fp, ft, pl, pages, npages, trust, bsz, mode);
        }
        FuWatermarks(wd, ln, et, npages, bsz, fo, ft);
        if (mode == 0) {
            FuStamps(wd, ln, et, pages, npages, cd, n, fo, fp, ft);
        }
        FuMergeFurniture(fo, fp, ft, ord);
        FuCompact(ln, cd, n);
        return before - Evidence.LnCount(ln);
    }
    public static int FuWrite(emon.Port.Cells fo, emon.Port.Cells fp, emon.Port.Cells ft, emon.Port.Cells pl, int npages, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells ledger, emon.Port.Cells tmp) {
        // Write what `fu-find` decided into the Model, after the paragraph stage: each page's label (page table), the
        // ledger rows, the `furniture` roots (parent -1: kept once, not in the flow) and the `label` of every `break`
        // milestone. The text goes through NFC and the ligature fold like every other text (SPEC 3.6). Answers 0.
        int p = 0;
        int r = 0;
        int t0 = 0;
        int n = 0;
        int l = 0;
        int i = 0;
        int q = 0;
        int prevpage = 0;
        int nf = 0;
        while (p < npages) {
            if ((emon.Port.CellsAt(pl, p * 3) > 0) && (emon.Port.CellsAt(pl, (p * 3) + 2) > 0)) {
                t0 = emon.Port.CellsLen(text);
                i = 0;
                while (i < emon.Port.CellsAt(pl, (p * 3) + 2)) {
                    Model.TextAppendCp(text, emon.Port.CellsAt(ft, emon.Port.CellsAt(pl, (p * 3) + 1) + i));
                    i += 1;
                }
                Model.PageSetLabel(pages, p, t0, emon.Port.CellsAt(pl, (p * 3) + 2));
            }
            p += 1;
        }
        r = 0;
        while (r < (emon.Port.CellsLen(fo) / 12)) {
            if (FoGet(fo, r, 0) == 1) {
                l = Model.LedgerAdd(ledger, FoGet(fo, r, 1), FoGet(fo, r, 2), FoGet(fo, r, 3), FoGet(fo, r, 4), FoGet(fo, r, 5), FoGet(fo, r, 6), FoGet(fo, r, 7), FoGet(fo, r, 8));
                t0 = emon.Port.CellsLen(text);
                Normalize.NzNfc(ft, FoGet(fo, r, 9), FoGet(fo, r, 9) + FoGet(fo, r, 10), text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                Model.LedgerSetText(ledger, l, t0, emon.Port.CellsLen(text) - t0);
            }
            if (FoGet(fo, r, 0) == 2) {
                nf = Model.NodeNew(nodes, Model.NkFurniture(), -1);
                Model.NodeSetSub(nodes, nf, FoGet(fo, r, 1));
                t0 = emon.Port.CellsLen(text);
                Normalize.NzNfc(ft, FoGet(fo, r, 4), FoGet(fo, r, 4) + FoGet(fo, r, 5), text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                Model.NodeSetText(nodes, nf, t0, emon.Port.CellsLen(text) - t0);
                Model.NodeSetConf(nodes, nf, FoGet(fo, r, 2));
                Model.NodeAddSrc(nodes, nf, FoGet(fo, r, 3));
                prevpage = 0;
                i = 0;
                while (i < FoGet(fo, r, 7)) {
                    q = (FoGet(fo, r, 6) + i) * 5;
                    Model.NodeAddRegion(nodes, regions, nf, emon.Port.CellsAt(fp, q), emon.Port.CellsAt(fp, q + 1), emon.Port.CellsAt(fp, q + 2), emon.Port.CellsAt(fp, q + 3), emon.Port.CellsAt(fp, q + 4));
                    if (emon.Port.CellsAt(fp, q) != prevpage) {
                        Model.NodeAddAttrInt(nodes, attrs, nf, Model.FkPages(), emon.Port.CellsAt(fp, q));
                        prevpage = emon.Port.CellsAt(fp, q);
                    }
                    i += 1;
                }
            }
            r += 1;
        }
        n = Model.NodeCount(nodes);
        i = 0;
        while (i < n) {
            if (Model.NodeKind(nodes, i) == Model.NkBreak()) {
                p = Model.NodeSub(nodes, i);
                if ((p >= 1) && (p <= Model.PageCount(pages))) {
                    if (Model.PageLabelLen(pages, p - 1) > 0) {
                        Model.NodeSetAttrText(nodes, attrs, i, Model.FkLabel(), Model.PageLabelStart(pages, p - 1), Model.PageLabelLen(pages, p - 1));
                    }
                }
            }
            i += 1;
        }
        return 0;
    }
}
